import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv3d_mish_tanh_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// Mish activation: mish(x) = x * tanh(softplus(x))
__forceinline__ __device__ float mishf(const float x) {
    float sp = logf(1.0f + expf(x));
    float tsp = tanhf(sp);
    return x * tsp;
}

__global__ void conv3d_mish_tanh_kernel(const float* __restrict__ input,
                                        const float* __restrict__ weight,
                                        const float* __restrict__ bias,
                                        float* __restrict__ output,
                                        int B, int C, int D, int H, int W,
                                        int OC, int kD, int kH, int kW,
                                        int outD, int outH, int outW,
                                        int padD, int padH, int padW,
                                        int strideD, int strideH, int strideW) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= B * OC * outD * outH * outW) return;

    int wOut = idx % outW;
    int tmp = idx / outW;
    int hOut = tmp % outH;
    tmp /= outH;
    int dOut = tmp % outD;
    tmp /= outD;
    int oc = tmp % OC;
    int n = tmp / OC;

    int dIn = dOut * strideD - padD;
    int hIn = hOut * strideH - padH;
    int wIn = wOut * strideW - padW;

    float val = bias[oc];

    for (int ic = 0; ic < C; ic++) {
        for (int kd = 0; kd < kD; kd++) {
            int d = dIn + kd;
            if (d < 0 || d >= D) continue;
            for (int kh = 0; kh < kH; kh++) {
                int h = hIn + kh;
                if (h < 0 || h >= H) continue;
                for (int kw_ = 0; kw_ < kW; kw_++) {
                    int w = wIn + kw_;
                    if (w < 0 || w >= W) continue;
                    float in_val = input[n * C * D * H * W
                                       + ic * D * H * W
                                       + d * H * W
                                       + h * W
                                       + w];
                    float wt_val = weight[oc * C * kD * kH * kW
                                         + ic * kD * kH * kW
                                         + kd * kH * kW
                                         + kh * kW
                                         + kw_];
                    val += in_val * wt_val;
                }
            }
        }
    }

    // Apply Mish
    val = mishf(val);
    // Apply Tanh
    val = tanhf(val);
    output[idx] = val;
}

torch::Tensor conv3d_mish_tanh_cuda(torch::Tensor input,
                                    torch::Tensor weight,
                                    torch::Tensor bias,
                                    int strideD,
                                    int strideH,
                                    int strideW,
                                    int padD,
                                    int padH,
                                    int padW) {
    auto B = input.size(0);
    auto C = input.size(1);
    auto D = input.size(2);
    auto H = input.size(3);
    auto W = input.size(4);

    auto OC = weight.size(0);
    auto kD = weight.size(2);
    auto kH = weight.size(3);
    auto kW = weight.size(4);

    int outD = (D + 2*padD - kD) / strideD + 1;
    int outH = (H + 2*padH - kH) / strideH + 1;
    int outW = (W + 2*padW - kW) / strideW + 1;

    auto options = torch::TensorOptions().dtype(input.dtype()).device(input.device());
    auto out = torch::zeros({B, OC, outD, outH, outW}, options);

    int total = B * OC * outD * outH * outW;
    const int block_size = 256;
    int grid_size = (total + block_size - 1) / block_size;

    conv3d_mish_tanh_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        B, C, D, H, W,
        OC, kD, kH, kW,
        outD, outH, outW,
        padD, padH, padW,
        strideD, strideH, strideW
    );
    return out;
}
"""

conv3d_mish_tanh_cpp_source = """
torch::Tensor conv3d_mish_tanh_cuda(torch::Tensor input,
                                    torch::Tensor weight,
                                    torch::Tensor bias,
                                    int strideD,
                                    int strideH,
                                    int strideW,
                                    int padD,
                                    int padH,
                                    int padW);
"""

fused_conv3d = load_inline(
    name="conv3d_mish_tanh",
    cpp_sources=conv3d_mish_tanh_cpp_source,
    cuda_sources=conv3d_mish_tanh_source,
    functions=["conv3d_mish_tanh_cuda"],
    verbose=False,
    extra_cflags=[""],
    extra_ldflags=[""],
)


class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride=1, padding=0):
        super(ModelNew, self).__init__()
        self.weight = nn.Parameter(torch.randn(out_channels, in_channels, kernel_size, kernel_size, kernel_size))
        self.bias = nn.Parameter(torch.zeros(out_channels))
        self.strideD = stride
        self.strideH = stride
        self.strideW = stride
        self.padD = padding
        self.padH = padding
        self.padW = padding
        self.conv3d_mish_tanh = fused_conv3d

    def forward(self, x):
        return self.conv3d_mish_tanh.conv3d_mish_tanh_cuda(
            x, self.weight, self.bias,
            self.strideD, self.strideH, self.strideW,
            self.padD, self.padH, self.padW
        )
